1242	  repository: number;
1243	  limiterConsume: number;
1244	  limiterRefusal: number;
1245	  passwordHash: number;
1246	  auditHash: number;
1247	  mailReservation: number;
1248	  tokenMint: number;
1249	  send: number;
1250	  mutation: number;
1251	  deliveryAudit: number;
1252	  registrationFailureAudit: number;
1253	}
1254	
1255	interface Rework7Occupancy {
1256	  readonly admitted: number;
1257	  readonly maximum: number;
1258	  readonly closing: boolean;
1259	  readonly admissions: number;
1260	  readonly releases: number;
1261	}
1262	
1263	type Rework7Activation = () => Promise<() => Promise<void>>;
1264	
1265	interface Rework7Harness {
1266	  readonly service: RegistrationService;
1267	  readonly policy: Rework7Policy;
1268	  readonly counters: Rework7Counters;
1269	  readonly sleeps: number[];
1270	  readonly errorLog: string[];
1271	  readonly admittedDuringSleep: number[];
1272	  readonly admittedAtCommit: number[];
1273	  readonly admittedAtHandoff: number[];
1274	  readonly heldPermits: Rework7Activation[];
1275	  readonly reservationHoldOccupancy: Rework7Occupancy[];
1276	  occupancy(): Rework7Occupancy;
1277	  openLookupGate(): void;
1278	  holdMailPermits(count: number): Promise<void>;
1279	  freeOneMailPermit(): Promise<void>;
1280	  register(index: number): Promise<unknown>;
1281	  resend(index: number): Promise<unknown>;
1282	  restore(): void;
1283	}
