1	import { createHmac, randomBytes, randomUUID } from "node:crypto";
2	import { performance } from "node:perf_hooks";
3	import type { PostgresIdentityRepository, AuthSourceContext } from "@debateai/db";
4	import type { AuthPolicy, AuthRouteLimit } from "@debateai/register";
5	import {
6	  Argon2InfrastructureError,
7	  createEmailBlindIndex,
8	  encrypt,
9	  generateDek,
10	  generatePseudonym,
11	  generateVerificationToken,
12	  hashPassword,
13	  hashVerificationToken,
14	  normalizeEmailForBlindIndex,
15	  type Argon2Executor,
16	  type UserDekStore
17	} from "@debateai/crypto";
18	import { MailDeliveryError, type MailSender } from "./mail-channel.js";
19	
20	export const REGISTRATION_PUBLIC_RESPONSE = Object.freeze({
21	  message: "If this address can be registered, verification instructions will arrive. Check your spam folder."
22	});
23	
24	export const RESEND_PUBLIC_RESPONSE = Object.freeze({
25	  message: "If this address is awaiting verification, new instructions will arrive. Check your spam folder."
26	});
27	
28	export interface RegisterInput {
29	  readonly email: string;
30	  readonly password: string;
31	  readonly recoveryEmail: string;
32	  readonly adultAffirmed: boolean;
33	}
34	
35	export interface RegistrationApplication {
36	  register(input: RegisterInput, source: AuthSourceContext): Promise<typeof REGISTRATION_PUBLIC_RESPONSE>;
37	  verifyEmail(input: { readonly token: string }, source: AuthSourceContext): Promise<{ readonly status: "active" }>;
38	  resendVerification(
39	    input: { readonly email: string },
40	    source: AuthSourceContext
41	  ): Promise<typeof RESEND_PUBLIC_RESPONSE>;
42	}
43	
44	/**
45	 * The single code every Argon2 pool failure surfaces as, from every source and
46	 * on every auth route. Exported so the HTTP error boundary can apply the same
47	 * envelope to a pool failure that never passed through this service.
48	 */
49	export const AUTH_RETRYABLE_UNAVAILABLE_CODE = "AUTH_TEMPORARILY_UNAVAILABLE";
50	
51	export class AuthFlowError extends Error {
52	  constructor(readonly code:
53	    | "AUTH_INPUT_INVALID"
54	    | "AUTH_RATE_LIMITED"
55	    | "AUTH_MAIL_BUSY"
56	    | "AUTH_REGISTRATION_FAILED"
57	    | "AUTH_TEMPORARILY_UNAVAILABLE"
58	    | "VERIFICATION_TOKEN_INVALID",
59	    options?: ErrorOptions
60	  ) {
61	    super(code, options);
62	    this.name = "AuthFlowError";
63	  }
64	
65	  get statusCode(): 400 | 429 | 503 {
66	    return this.code === "AUTH_RATE_LIMITED" ? 429
67	      : this.code === "AUTH_REGISTRATION_FAILED" || this.code === "AUTH_MAIL_BUSY"
68	        || this.code === "AUTH_TEMPORARILY_UNAVAILABLE" ? 503 : 400;
69	  }
70	}
71	
72	/**
73	 * The ONE envelope every Argon2 pool failure gets, on every auth route and from
74	 * every source — password hashing, audit derivation, verification, resend and
75	 * account provisioning alike.
76	 *
77	 * Two properties matter. It is constant and secret-free: the body carries the
78	 * code and nothing else, so `ARGON2_POOL_CAPACITY_EXHAUSTED` vs
79	 * `ARGON2_WORKER_FAILED` — which describes internal capacity state — never
80	 * reaches a client, and the generic 500 handler (whose body is
81	 * `knownError.message`) is never the path these take. And it is a retryable
82	 * 503, not a 500: the request failed for want of a worker, not because the
83	 * credentials were wrong. The typed cause is retained on `cause` for operators.
84	 */
85	function asAuthFlowFailure(error: unknown): unknown {
86	  return error instanceof Argon2InfrastructureError
87	    ? new AuthFlowError("AUTH_TEMPORARILY_UNAVAILABLE", { cause: error })
88	    : error;
89	}
90	
91	type AuthRoute = "register" | "verify" | "resend";
92	const AUTH_ROUTES = Object.freeze(["register", "verify", "resend"] as const);
93	
94	interface RefusalAggregate {
95	  readonly windowStartedAt: number;
96	  readonly actorToken: string;
97	  readonly occurredAt: Date;
98	  readonly source: AuthSourceContext;
99	  count: number;
100	  ipCount: number;
101	  addressCount: number;
102	}
103	
104	export class InProcessAuthRateLimiter {
105	  private readonly slotCounts: Uint8Array;
106	  private readonly slotHeads: Uint8Array;
107	  private readonly slotSaturatedUntil: Float64Array;
108	  private readonly slotExpiries: Float64Array;
109	  private readonly slotRowsByRoute: Readonly<Record<
110	    AuthRoute,
111	    readonly Readonly<{ offset: number; width: number }>[]
112	  >>;
113	  private readonly slotOffsetByRoute: Readonly<Record<AuthRoute, number>>;
114	  private readonly expiryOffsetByRoute: Readonly<Record<AuthRoute, number>>;
115	  private readonly slotHashKey: Buffer;
116	  private readonly occupiedSlotsByRoute: Record<AuthRoute, number> = {
117	    register: 0,
118	    verify: 0,
119	    resend: 0
120	  };
121	  private readonly refusalAggregates = new Map<AuthRoute, RefusalAggregate>();
122	
123	  constructor(
124	    private readonly policy: Readonly<Record<AuthRoute, AuthRouteLimit>>,
125	    private readonly bucketCapacity: number,
126	    private readonly refusalAuditIntervalMs: number,
127	    slotHashKey: Uint8Array = randomBytes(32)
128	  ) {
129	    if (!Number.isInteger(bucketCapacity) || bucketCapacity < 1
130	      || !Number.isInteger(refusalAuditIntervalMs) || refusalAuditIntervalMs < 1
131	      || slotHashKey.byteLength < 16
132	      || AUTH_ROUTES.some((route) => !Number.isInteger(policy[route].admissionPerSource)
133	        || policy[route].admissionPerSource < 1 || policy[route].admissionPerSource > 255)) {
134	      throw new TypeError("AUTH_RATE_LIMIT_POLICY_INVALID");
135	    }
136	    const slotCapacity = bucketCapacity * AUTH_ROUTES.length;
137	    this.slotCounts = new Uint8Array(slotCapacity);
138	    this.slotHeads = new Uint8Array(slotCapacity);
139	    this.slotSaturatedUntil = new Float64Array(slotCapacity);
140	    let expiryOffset = 0;
141	    this.slotOffsetByRoute = Object.freeze(Object.fromEntries(AUTH_ROUTES.map((route, routeIndex) =>
142	      [route, routeIndex * bucketCapacity]
143	    )) as Record<AuthRoute, number>);
144	    this.expiryOffsetByRoute = Object.freeze(Object.fromEntries(AUTH_ROUTES.map((route) => {
145	      const offset = expiryOffset;
146	      expiryOffset += bucketCapacity * policy[route].admissionPerSource;
147	      return [route, offset];
148	    })) as Record<AuthRoute, number>);
149	    this.slotExpiries = new Float64Array(expiryOffset);
150	    const firstWidth = bucketCapacity === 1 ? 1 : Math.floor(bucketCapacity / 2);
151	    this.slotRowsByRoute = Object.freeze(Object.fromEntries(AUTH_ROUTES.map((route, routeIndex) => {
152	      const routeOffset = this.slotOffsetByRoute[route];
153	      return [route, bucketCapacity === 1
154	        ? Object.freeze([Object.freeze({ offset: routeOffset, width: 1 })])
155	        : Object.freeze([
156	            Object.freeze({ offset: routeOffset, width: firstWidth }),
157	            Object.freeze({
158	              offset: routeOffset + firstWidth,
159	              width: bucketCapacity - firstWidth
160	            })
161	          ])];
162	    })) as Record<AuthRoute, readonly Readonly<{ offset: number; width: number }>[]>);
163	    this.slotHashKey = Buffer.from(slotHashKey);
164	  }
165	
166	  private slotIndexes(route: AuthRoute, key: string): readonly number[] {
167	    const digest = createHmac("sha256", this.slotHashKey).update(key, "utf8").digest();
168	    return this.slotRowsByRoute[route].map((row, index) =>
169	      row.offset + (digest.readUInt32BE(index * 4) % row.width)
170	    );
171	  }
172	
173	  private expiryBase(route: AuthRoute, index: number, limit: number): number {
174	    return this.expiryOffsetByRoute[route]
175	      + (index - this.slotOffsetByRoute[route]) * limit;
176	  }
177	
178	  private activeCount(route: AuthRoute, index: number, limit: number, now: number): number {
179	    let count = this.slotCounts[index]!;
180	    let head = this.slotHeads[index]!;
181	    const wasOccupied = count > 0 || this.slotSaturatedUntil[index]! > 0;
182	    const expiryBase = this.expiryBase(route, index, limit);
183	    while (count > 0 && this.slotExpiries[expiryBase + head]! <= now) {
184	      head = (head + 1) % limit;
185	      count -= 1;
186	    }
187	    if (this.slotSaturatedUntil[index]! <= now) this.slotSaturatedUntil[index] = 0;
188	    if (count === 0) head = 0;
189	    this.slotCounts[index] = count;
190	    this.slotHeads[index] = head;
191	    if (wasOccupied && count === 0 && this.slotSaturatedUntil[index] === 0) {
192	      this.occupiedSlotsByRoute[route] -= 1;
193	    }
194	    return count;
195	  }
196	
197	  /**
198	   * Bounded memory, exact per-key counting, and zero false refusal at saturation
199	   * cannot coexist. This keyed, route-isolated two-row fixed-slot sketch gives up
200	   * exactness only on same-route collisions: colliding sources share counts, so
201	   * information loss can over-count/refuse but can never mint a fresh budget.
202	   * Slots are never evicted or reassigned, so an at-limit source receives no
203	   * early amnesty. The random per-process key makes targeted collisions
204	   * impractical while keeping the ruled slot count as the hard memory bound.
205	   *
206	   * D3 residual: raw IP exists transiently in the request and HMAC input but is
207	   * not retained in slot state. RefusalAggregate intentionally retains one
208	   * AuthSourceContext per route until the bounded audit-flush window; that map is
209	   * capped at three routes, is never logged/persisted raw, and the repository
210	   * hashes it at its boundary. A memory-hard per-request KDF is not justified for
211	   * this bounded ephemeral state. Slot state is held in preallocated typed
212	   * arrays, so attacker-driven occupancy changes values but never allocates a
213	   * retained object or array and resident storage converges on the ruled bound.
214	   */
215	  private take(
216	    route: AuthRoute,
217	    key: string,
218	    limit: number,
219	    windowMs: number,
220	    now: number
221	  ): boolean {
222	    const indexes = this.slotIndexes(route, key);
223	    const counts = indexes.map((index) => this.activeCount(route, index, limit, now));
224	    const estimatedCount = Math.min(...indexes.map((index, offset) =>
225	      this.slotSaturatedUntil[index]! > now ? limit : counts[offset]!
226	    ));
227	    if (estimatedCount >= limit) return false;
228	
229	    const expiresAt = now + windowMs;
230	    for (let offset = 0; offset < indexes.length; offset += 1) {
231	      const index = indexes[offset]!;
232	      const count = counts[offset]!;
233	      if (count === 0 && this.slotSaturatedUntil[index] === 0) {
234	        this.occupiedSlotsByRoute[route] += 1;
235	      }
236	      if (this.slotSaturatedUntil[index]! > now || count >= limit) {
237	        this.slotSaturatedUntil[index] = Math.max(
238	          this.slotSaturatedUntil[index]!,
239	          expiresAt
240	        );
241	      } else {
242	        const head = this.slotHeads[index]!;
243	        const tail = (head + count) % limit;
244	        this.slotExpiries[this.expiryBase(route, index, limit) + tail] = expiresAt;
245	        this.slotCounts[index] = count + 1;
246	      }
247	    }
248	    return true;
