269	  aggregateRefusal(input: {
270	    readonly route: AuthRoute;
271	    readonly scope: "ip" | "address";
272	    readonly actorToken: string;
273	    readonly now: Date;
274	    readonly source: AuthSourceContext;
275	  }): Readonly<{
276	    finalized: Readonly<RefusalAggregate> | null;
277	    startedWindow: boolean;
278	    windowStartedAt: number;
279	  }> {
280	    const now = input.now.getTime();
281	    const windowStartedAt = Math.floor(now / this.refusalAuditIntervalMs) * this.refusalAuditIntervalMs;
282	    const current = this.refusalAggregates.get(input.route);
283	    const finalized = current !== undefined && current.windowStartedAt !== windowStartedAt
284	      ? Object.freeze({ ...current })
285	      : null;
286	    const aggregate = current?.windowStartedAt === windowStartedAt
287	      ? { ...current }
288	      : {
289	          windowStartedAt,
290	          actorToken: input.actorToken,
291	          occurredAt: input.now,
292	          source: input.source,
293	          count: 0,
294	          ipCount: 0,
295	          addressCount: 0
296	        };
297	    if (aggregate.count < Number.MAX_SAFE_INTEGER) {
298	      aggregate.count += 1;
299	      if (input.scope === "ip") aggregate.ipCount += 1;
300	      else aggregate.addressCount += 1;
301	    }
302	    this.refusalAggregates.set(input.route, aggregate);
303	    return Object.freeze({
304	      finalized,
305	      startedWindow: current?.windowStartedAt !== windowStartedAt,
306	      windowStartedAt
307	    });
308	  }
