436	    windowStartedAt: number;
437	    timer: ReturnType<typeof setTimeout>;
438	  }> | undefined;
439	  /**
440	   * THE writer for this route while one is running. Every path — the public
441	   * refusal, the deadline timer, and every concurrent shutdown drain — joins
442	   * this exact promise rather than starting a private one, which is what makes
443	   * a second write of an in-flight window impossible and makes a drain unable
444	   * to return while this route still owes a write.
