493	    readonly limiter: InProcessAuthRateLimiter;
494	    /**
495	     * Off-thread Argon2. Injected, never constructed here: exactly one
496	     * process-owned pool is created in main.ts and shared with the repository,
497	     * so there is no module singleton, pool-per-request or second pool.
498	     */
499	    readonly argon2: Argon2Executor;
