612	  /**
613	   * Hands one finalized window to the route coordinator, in window order so a
614	   * recovery writes retained windows deterministically oldest-first.
615	   */
616	  private enqueueRefusalAggregate(route: AuthRoute, aggregate: Readonly<RefusalAggregate>): void {
617	    const { queue } = this.refusalAuditRoute(route);
618	    const at = queue.findIndex((queued) => queued.windowStartedAt > aggregate.windowStartedAt);
619	    if (at < 0) queue.push(aggregate);
620	    else queue.splice(at, 0, aggregate);
621	  }
622	
623	  /**
624	   * Finalizes `windowStartedAt` INTO the queue, exactly once.
625	   *
626	   * The guard is the whole point: a timer that fires for a window which is no
627	   * longer the active one has already been superseded — its aggregate left the
628	   * limiter as the rollover snapshot and is queued — so it must not finalize
629	   * anything, or it would enqueue a second copy and cancel the successor's
630	   * deadline along the way.
631	   */
632	  private finalizeRefusalWindow(route: AuthRoute, windowStartedAt: number): void {
633	    const coordinator = this.refusalAuditRoutes.get(route);
634	    if (coordinator?.active?.windowStartedAt !== windowStartedAt) return;
635	    clearTimeout(coordinator.active.timer);
636	    coordinator.active = undefined;
637	    // The limiter releases its copy HERE; the queue is the only copy from now on.
638	    const aggregate = this.dependencies.limiter.finalizeRefusalAggregate(route, windowStartedAt);
639	    if (aggregate !== null) this.enqueueRefusalAggregate(route, aggregate);
640	  }
641	
642	  /**
643	   * Returns THE route writer, starting it only if none is running.
644	   *
645	   * The running writer drains the whole queue, so an aggregate enqueued while
646	   * it works is picked up by that same writer instead of by a second one. A
647	   * caller therefore always gets a promise that covers everything this route
648	   * currently owes, and every caller gets the SAME promise.
649	   */
650	  private startRefusalAuditPump(route: AuthRoute): Promise<void> {
651	    const coordinator = this.refusalAuditRoute(route);
652	    if (coordinator.writer !== undefined) return coordinator.writer;
653	    if (coordinator.queue.length === 0) {
654	      this.releaseRefusalAuditRoute(route);
655	      return Promise.resolve();
656	    }
657	    const writer = this.pumpRefusalAuditQueue(route, coordinator);
658	    coordinator.writer = writer;
659	    return writer;
660	  }
661	
662	  private async pumpRefusalAuditQueue(
663	    route: AuthRoute,
664	    coordinator: RefusalAuditCoordinator
665	  ): Promise<void> {
666	    try {
667	      // Dequeued one at a time and only AFTER its own write lands, so a failure
668	      // part-way through neither loses an unwritten window nor rewrites a
669	      // durable one — the rejected head stays at the front for the retry.
670	      //
671	      // Removal is by IDENTITY, never by position: the queue is ordered by
672	      // window, so a window finalized while this write is in flight — after a
673	      // backward wall-clock step, a real refusal can open an OLDER window — is
674	      // sorted in front of the aggregate being written. A positional shift()
675	      // would then discard that never-written window and re-attempt the one
676	      // that just landed, and `recordRateLimitRefusal` has no dedup key.
677	      while (coordinator.queue.length > 0) {
678	        const writing = coordinator.queue[0]!;
679	        await this.recordRefusalAggregate(route, writing);
680	        const at = coordinator.queue.indexOf(writing);
681	        if (at >= 0) coordinator.queue.splice(at, 1);
682	      }
683	    } finally {
684	      coordinator.writer = undefined;
685	      this.releaseRefusalAuditRoute(route);
686	    }
687	  }
688	
689	  /**
690	   * Opens `windowStartedAt` as this route's active window and arms its
691	   * aggregation deadline. Rollover ADVANCES the window: the queue and the
692	   * writer are untouched, so a predecessor still being persisted keeps its one
693	   * owner.
694	   */
695	  private scheduleRefusalAuditFlush(route: AuthRoute, windowStartedAt: number, now: Date): void {
696	    const coordinator = this.refusalAuditRoute(route);
697	    if (coordinator.active?.windowStartedAt === windowStartedAt) return;
698	    if (coordinator.active !== undefined) clearTimeout(coordinator.active.timer);
699	
700	    const delay = Math.max(0,
701	      windowStartedAt + this.dependencies.policy.rateLimitRefusalAuditIntervalMs - now.getTime()
702	    );
703	    const timer = setTimeout(() => {
704	      // The ORDINARY deadline path stays fire-and-forget: it logs, leaves the
705	      // unwritten window queued for a later drain, and never touches a request.
706	      this.finalizeRefusalWindow(route, windowStartedAt);
707	      void this.startRefusalAuditPump(route).catch(() => {
708	        console.error(
709	          `[AUTH_RATE_LIMIT_AUDIT_RECORD_FAILED] route=${route} window=${new Date(windowStartedAt).toISOString()}`
710	        );
711	      });
712	    }, delay);
713	    timer.unref();
714	    coordinator.active = Object.freeze({ windowStartedAt, timer });
715	  }
716	
717	  /**
718	   * Awaits every pending refusal-audit window, firing each one NOW rather than
719	   * waiting out its aggregation deadline.
720	   *
721	   * That deadline is the ruled `rateLimitRefusalAuditIntervalMs` aggregation
722	   * window, so simply awaiting it would stall a shutdown drain for up to a
723	   * minute per route — and because the timer is unref'd, a process that exited
724	   * first would lose the durable refusal row entirely. Firing early changes no
725	   * aggregation semantics and no audit content: the same flush body runs, the
726	   * same row is written, only the wait is removed.
727	   *
728	   * Unlike the ordinary deadline path, this drain OBSERVES persistence. It is
729	   * the last chance to write the row before the process goes away, and its
730	   * caller uses it to decide that the Argon2 surface may be torn down. So a
731	   * failed write propagates here rather than being logged and forgotten: the
732	   * retained aggregate stays pending and retryable, and shutdown is not told
733	   * that work it never durably recorded is done.
734	   */
735	  async drainRateLimitAuditFlushes(): Promise<void> {
736	    let failure: unknown;
737	    let failed = false;
738	    // Sequential rather than raced, so one route's failure never cancels
739	    // another route's in-flight write half-way through.
740	    for (const route of [...this.refusalAuditRoutes.keys()]) {
741	      await this.drainRefusalAuditRoute(route).catch((error: unknown) => {
742	        if (!failed) {
743	          failed = true;
744	          failure = error;
745	        }
746	      });
747	    }
748	    if (failed) throw failure;
749	  }
750	
751	  private async drainRefusalAuditRoute(route: AuthRoute): Promise<void> {
752	    for (;;) {
753	      const coordinator = this.refusalAuditRoutes.get(route);
754	      if (coordinator === undefined) return;
755	      // Firing the active window early is what bounds the drain; the flush body
756	      // and the row it produces are identical to the deadline path's.
757	      if (coordinator.active !== undefined) {
758	        this.finalizeRefusalWindow(route, coordinator.active.windowStartedAt);
759	      }
760	      if (coordinator.writer === undefined && coordinator.queue.length === 0) return;
761	      // Joining THE route writer — never a private copy of the queue — is what
762	      // stops this drain returning while a write it does not own is still in
763	      // flight, and what coalesces concurrent drains onto one write per window.
764	      // A rejection propagates: shutdown is never told that work it never
765	      // durably recorded is done, and the rejected window stays queued.
766	      await this.startRefusalAuditPump(route);
767	      // The writer just joined may have been a PREDECESSOR's, finishing before
768	      // this drain's own finalization was enqueued, so re-check rather than
769	      // assume this route is now clear.
770	    }
771	  }
