773	  private activateMailDispatch(
774	    enforceMinimum = false,
775	    minimumReservationMs: number = this.dependencies.policy.channel.mailDispatchMinimumReservationMs
776	  ): MailDispatchRelease {
777	    const activatedAt = performance.now();
778	    let release: Promise<void> | undefined;
779	    return () => {
780	      if (release !== undefined) return release;
781	      release = (async () => {
782	        const minimum = enforceMinimum || this.waitingMailDispatches.length > 0
783	          ? minimumReservationMs
784	          : 0;
785	        const remaining = minimum - (performance.now() - activatedAt);
786	        if (remaining > 0) {
787	          await new Promise<void>((resolve) => setTimeout(resolve, remaining));
788	        }
789	      })().then(async () => {
790	        this.mailDispatchReservations -= 1;
791	        const next = this.waitingMailDispatches.shift();
792	        if (next !== undefined) {
793	          clearTimeout(next.timeout);
794	          this.mailDispatchReservations += 1;
795	          next.resolve(() => this.scheduleMailDispatchActivation(
796	            true, next.minimumReservationMs, next.activationSpacingMs
797	          ));
798	        }
799	      });
800	      return release;
801	    };
802	  }
