804	  private async scheduleMailDispatchActivation(
805	    enforceMinimum = false,
806	    minimumReservationMs: number = this.dependencies.policy.channel.mailDispatchMinimumReservationMs,
807	    activationSpacingMs: number = this.dependencies.policy.channel.mailDispatchActivationSpacingMs
808	  ): Promise<MailDispatchRelease> {
809	    const now = performance.now();
810	    const scheduledAt = Math.max(now, this.nextMailDispatchActivationAt);
811	    this.nextMailDispatchActivationAt = scheduledAt
812	      + activationSpacingMs;
813	    const delay = scheduledAt - now;
814	    if (delay > 0) {
815	      await new Promise<void>((resolve) => setTimeout(resolve, delay));
816	    }
817	    return this.activateMailDispatch(enforceMinimum, minimumReservationMs);
818	  }
