820	  private flushMailCapacitySignal(windowStartedAt: number): void {
821	    const aggregate = this.mailCapacitySignalAggregate;
822	    if (aggregate === undefined || aggregate.windowStartedAt !== windowStartedAt) return;
823	    clearTimeout(aggregate.timer);
