840	    if (active !== undefined) this.flushMailCapacitySignal(active.windowStartedAt);
841	    const windowStartedAt = now;
842	    const timer = setTimeout(
843	      () => this.flushMailCapacitySignal(windowStartedAt),
844	      windowMs
845	    );
846	    timer.unref();
847	    this.mailCapacitySignalAggregate = {
848	      windowStartedAt,
849	      correlationId,
850	      count: 1,
851	      timer
