950	    const duplicate = "kind" in input && input.kind === "duplicate" ? input : undefined;
951	    let delivery: VerificationDelivery | undefined = duplicate === undefined
952	      ? input as VerificationDelivery
953	      : undefined;
954	    const deliveryAttemptId = delivery?.channelBindingId;
955	    let pending!: Promise<void>;
956	    pending = new Promise<void>((resolve) => setImmediate(resolve))
957	      .then(async () => {
958	        if (duplicate !== undefined) {
