1020	        input.requestedAt.getTime() + this.dependencies.policy.verification.tokenTtlMs
1021	      );
1022	      const dek = generateDek();
1023	      try {
1024	        const keyId = `user-dek:${userId}`;
1025	        const emailCiphertext = encrypt(dek, Buffer.from(input.email, "utf8"), [
1026	          "identity", "user.email_ciphertext", userId, "run:none", userId, keyId, "1"
1027	        ]);
1028	        const recoveryEmailCiphertext = encrypt(dek, Buffer.from(input.recoveryEmail, "utf8"), [
1029	          "identity", "user.recovery_email_ciphertext", userId, "run:none", userId, keyId, "1"
1030	        ]);
1031	        const created = await this.dependencies.repository.createPendingAccount({
1032	          userId,
1033	          emailBlindIndex: input.emailBlindIndex,
1034	          emailCiphertext,
