824	export async function readAuthPolicy(pool: Pool, registerVersion: number): Promise<AuthPolicy> {
825	  if (!Number.isInteger(registerVersion) || registerVersion < 1) {
826	    throw new TypeError("A positive register version is required for auth policy");
827	  }
828	  const result = await pool.query<{ row_key: string; value_json: unknown; source_ref: string }>(`
829	    SELECT row_key,value_json,source_ref FROM register.register_row
830	    WHERE register_version=$1 AND row_key=ANY($2::text[])
831	  `, [registerVersion, AUTH_POLICY_ROW_KEYS]);
832	  return authPolicyFromRegisterRows(result.rows.map((row) => ({
833	    rowKey: row.row_key as AuthPolicyRegisterRow["rowKey"],
834	    value: row.value_json as Readonly<Record<string, unknown>>,
835	    sourceRef: row.source_ref
836	  })));
837	}
