    order: rows.rows.map((row) => Object.freeze({
      eventType: row.event_type, actorKeyRef: row.actor_key_ref, occurredAt: row.occurred_at
    })),
    rootCount: Number(roots.rows[0]!.roots),
    totalRows: Number(roots.rows[0]!.total)
  });
}


