      }
    };
    const monitor = await database.pool.connect();
    const openedAt = performance.now();
    const phase = (name: string): void => console.info(
      `[T9 RESEND RACE PHASE] ${name} t=${(performance.now() - openedAt).toFixed(0)}ms`
    );
    try {
