    const originalSignalMailCapacity = inspectedService.signalMailCapacity.bind(flow.service);
    const retainedRefusalObjects: Array<Readonly<{
      s3dRetainedRefusalMarker: true;
      refusalIndex: number;
    }>> = [];
    if (retainOneObjectPerRefusal) {
