      Promise.all(queued), Promise.all(schedulerDrainNulls)
    ]);
    const existing = outcomes.filter((outcome) => outcome.arm === "existing")
      .map((outcome) => outcome.elapsedMs);
    const missing = outcomes.filter((outcome) => outcome.arm === "missing")
