    // unchanged, so the production failure path keeps its exact behaviour.
    flow.repository.recordVerificationDelivery = async (
      input: Parameters<typeof shippedRecordDelivery>[0]
    ): Promise<void> => {
      try {
        await shippedRecordDelivery(input);
      } catch (error) {
