  });

  it("S3a A2 clamps empty and whitespace User-Agent values for all auth-route audit writes", async () => {
    for (const [label, userAgent, ip] of [
      ["empty", "", "192.0.2.241"],
      ["whitespace", "   ", "192.0.2.242"]
    ] as const) {
      const flow = buildService();
