        + `tuned_ceiling_mib=${control.tunedCeilingMib.toFixed(3)} `
        + `plateau_spread_mib=${control.plateauSpreadMib.toFixed(3)} `
        + `retained_total_mib=${control.retainedTotalMib} `
        + `measured_total_count=${control.measuredCapacityCount}`
      );
