        generatedTokenHashes.add(hashVerificationToken(token));
        return token;
      }
    });
    const capacityError = vi.spyOn(console, "error").mockImplementation(() => undefined);
    const heapCanary = Buffer.from("C".repeat(43), "utf8").toString("utf8");
