    const sustainedLoad = process.env.S3D_CADENCE_SUSTAINED_LOAD === "1";
    expect([30, 45, 60]).toContain(registrationCadenceMs);
    const cadencePolicy = registrationCadenceMs === 45
      ? basePolicy
      : Object.freeze({
