      audit_id: string;
      prev_hash: Buffer | null;
      this_hash: Buffer;
      actor_ciphertext: null;
      actor_key_ref: string;
      event_type: string;
      target_type: string;
      target_id: string;
      occurred_at: Date;
      source_context: Record<string, unknown>;
      decision: string;
      success: boolean;
      justification: string | null;
      depth: number;
