import hashlib
import pathlib
import subprocess
import sys

ROOT = pathlib.Path("/Users/vladmihaimiron/Documents/DebateAIRO/dialectical-engine")
SCRATCH = pathlib.Path("/tmp/t1r7")

TARGETS = {
    "registration": ROOT / "apps/api/src/registration.ts",
    "main": ROOT / "apps/api/src/main.ts",
    "policy": ROOT / "packages/register/src/auth-policy.ts",
}
BACKUPS = {
    "registration": SCRATCH / "registration.baseline.ts",
    "main": SCRATCH / "main.baseline.ts",
    "policy": SCRATCH / "auth-policy.baseline.ts",
}

UNIT = ["node_modules/.bin/vitest", "run", "tests/unit/registration.test.ts", "-t", "T1 rework7"]
ARCH = ["node_modules/.bin/vitest", "run", "tests/architecture/t1-argon2-worker-contract.test.ts",
        "-t", "rework7|shutdown drains|clamp-absorption"]

