        const email = normalizeEmailForBlindIndex(input.email);
        const recoveryEmail = normalizeEmailForBlindIndex(input.recoveryEmail);
        const emailBlindIndex = createEmailBlindIndex(this.dependencies.blindIndexKey, email);
        const existing = await this.dependencies.repository.findAuditIdentityByBlindIndex(emailBlindIndex);
"""
ACQUIRE_ORDER_NEW = """        const email = normalizeEmailForBlindIndex(input.email);
        const recoveryEmail = normalizeEmailForBlindIndex(input.recoveryEmail);
        const emailBlindIndex = createEmailBlindIndex(this.dependencies.blindIndexKey, email);
        const existing = await this.dependencies.repository.findAuditIdentityByBlindIndex(emailBlindIndex);
        releaseAdmission = this.acquireRegistrationAdmission(correlationId);
"""

HOLD_OLD = """              try {
                // Register the hold in `pendingMailDispatches` FIRST, so a
                // shutdown drain can see the work, and only then hand the budget
                // back — without waiting out the reservation lease, which would
                // hold an admission slot for seconds against a request that no
                // longer exists.
                this.dispatchMailReservationHold(await activate());
              } finally {
                admission?.();
              }
"""
HOLD_RELEASE_EARLY = """              try {
                const granted = await activate();
                admission?.();
                this.dispatchMailReservationHold(granted);
              } finally {
                admission?.();
              }
"""
HOLD_RETAIN_THROUGH_LEASE = """              try {
                const granted = await activate();
                this.dispatchMailReservationHold(granted);
                await new Promise<void>((resolve) => setTimeout(resolve,
                  this.dependencies.policy.channel.registrationMailDispatchMinimumReservationMs));
              } finally {
                admission?.();
              }
"""

IDEMPOTENCE_OLD = """    let released = false;
    return () => {
      if (released) return;
      released = true;
      this.registrationAdmissionsHeld -= 1;
"""
IDEMPOTENCE_NEW = """    return () => {
      this.registrationAdmissionsHeld -= 1;
"""

EXCLUSIVE_OLD = '      if (admissionOwner === "local") releaseAdmission?.();'
EXCLUSIVE_NEW = "      releaseAdmission?.();"

PROVISION_OLD = """          }));
        } catch (provisionError) {
"""
PROVISION_NEW = """          }));
          releaseAdmission?.();
        } catch (provisionError) {
"""

TIMER_OLD = """        const index = this.waitingMailDispatches.indexOf(waiting);
        if (index < 0) return;
        this.waitingMailDispatches.splice(index, 1);
        this.signalMailCapacity(request.correlationId);
"""
TIMER_NEW = """        const index = this.waitingMailDispatches.indexOf(waiting);
        if (index < 0) return;
        this.signalMailCapacity(request.correlationId);
"""

SHUTDOWN_OLD = """  await registration.drainRegistrationAdmissions();
  await registration.drainMailDispatches();
"""
SHUTDOWN_NEW = """  await registration.drainMailDispatches();
  await registration.drainRegistrationAdmissions();
"""

MUTANTS = [
    ("M01-raise-the-103-cap", "registration", UNIT, [(
        """    if (this.registrationAdmissionsHeld
      >= this.dependencies.policy.channel.structuralMaximumConcurrentRegistrations) {""",
        """    if (this.registrationAdmissionsHeld
      >= this.dependencies.policy.channel.structuralMaximumConcurrentRegistrations + 1_000_000) {""",
    )]),
    ("M02-acquire-after-first-repository-await", "registration", UNIT,
     [(ACQUIRE_ORDER_OLD, ACQUIRE_ORDER_NEW)]),
    ("M03-release-at-commit", "registration", UNIT, [(PROVISION_OLD, PROVISION_NEW)]),
    ("M04-release-before-hold-registered", "registration", UNIT,
