    ("M05-retain-admission-through-the-reservation-hold", "registration", UNIT,
     [(HOLD_OLD, HOLD_RETAIN_THROUGH_LEASE)]),
    ("M06-owners-not-mutually-exclusive", "registration", UNIT,
     [(EXCLUSIVE_OLD, EXCLUSIVE_NEW)]),
