     [(IDEMPOTENCE_OLD, IDEMPOTENCE_NEW)]),
    ("M08-release-non-idempotent-with-two-owners", "registration", UNIT,
     [(IDEMPOTENCE_OLD, IDEMPOTENCE_NEW), (EXCLUSIVE_OLD, EXCLUSIVE_NEW)]),
