            this.dependencies.policy.channel.registrationMailDispatchQueueWaitTimeoutMs""",
        """          waitDeadlineMs:
            this.dependencies.policy.channel.mailDispatchQueueWaitTimeoutMs""",
    )]),
    ("M10-28s-deadline-for-resend", "registration", UNIT, [(
        "    const activate = await this.reserveMailDispatchPermit({ correlationId });",
        "    const activate = await this.reserveMailDispatchPermit({ correlationId,\n"
        "      waitDeadlineMs: this.dependencies.policy.channel"
        ".registrationMailDispatchQueueWaitTimeoutMs });",
    )]),
    ("M11-timed-out-waiter-left-retained", "registration", UNIT, [(TIMER_OLD, TIMER_NEW)]),
