    )]),
    ("M11-timed-out-waiter-left-retained", "registration", UNIT, [(TIMER_OLD, TIMER_NEW)]),
    ("M12-mail-drain-before-admission-drain", "main", ARCH, [(SHUTDOWN_OLD, SHUTDOWN_NEW)]),
    ("M13-decision-version-2-still-CURRENT", "policy", ARCH, [(
        '          status: "SUPERSEDED_BY_DECISION_VERSION_3;'
        '_CAPACITY_CLAIM_CONTRADICTED_BY_UNCHANGED_CODE_EVIDENCE",',
        '          status: "CURRENT",',
    )]),
    ("M14-positive-current-n-star-published", "policy", ARCH, [(
        "          current_positive_clamp_absorption_n_star: null,",
        "          current_positive_clamp_absorption_n_star: 3,",
    )]),
    ("M15-capacity-from-observed-completion", "registration", UNIT, [(
        "      admitted: this.registrationAdmissionsHeld,",
        "      admitted: this.pendingMailDispatches.size,",
    )]),
]


def digest(path):
    return hashlib.sha256(path.read_bytes()).hexdigest()


def main():
    out = []
    baseline = {name: digest(path) for name, path in BACKUPS.items()}
    for name, target, gate, edits in MUTANTS:
        path = TARGETS[target]
        original = BACKUPS[target].read_text()
        if digest(path) != baseline[target]:
            print(f"ABORT: {path} not at baseline before {name}")
            return 2
        mutated = original
        for old, new in edits:
            if mutated.count(old) != 1:
                print(f"ABORT: {name} anchor matched {mutated.count(old)} times, expected 1")
                return 2
            mutated = mutated.replace(old, new, 1)
        if mutated == original:
            print(f"ABORT: {name} produced no change")
            return 2
        path.write_text(mutated)
        mutant_sha = digest(path)
        run = subprocess.run(gate, cwd=ROOT, capture_output=True, text=True)
        blob = run.stdout + run.stderr
        failed = sum(1 for line in blob.splitlines() if line.startswith(" FAIL "))
        summary = next((line.strip() for line in blob.splitlines()
                        if line.strip().startswith("Tests ")), "NO TEST SUMMARY")
        reasons = [line.strip() for line in blob.splitlines()
                   if line.startswith(" FAIL ")][:4]
        path.write_text(original)
        restored = digest(path)
        verdict = "KILLED" if run.returncode != 0 and failed > 0 else "SURVIVOR"
        if restored != baseline[target]:
            print(f"ABORT: {name} restore not byte-identical")
            return 2
        out.append({
            "name": name, "file": str(path.relative_to(ROOT)), "gate": " ".join(gate[2:]),
            "mutant_sha": mutant_sha, "status": run.returncode, "failed_files": failed,
            "summary": summary, "reasons": reasons, "verdict": verdict,
            "restored_sha": restored,
        })
        print(f"{verdict:9s} {name}  status={run.returncode}  {summary}")
    lines = []
    for row in out:
        lines.append(f"--- {row['name']} ---")
        lines.append(f"  file            : {row['file']}")
        lines.append(f"  gate            : vitest run {row['gate']}")
        lines.append(f"  mutant sha256   : {row['mutant_sha']}")
        lines.append(f"  raw status      : {row['status']}")
        lines.append(f"  failing files   : {row['failed_files']}")
        lines.append(f"  vitest summary  : {row['summary']}")
        for reason in row["reasons"]:
            lines.append(f"  killed by       : {reason}")
        lines.append(f"  verdict         : {row['verdict']}")
        lines.append(f"  restored sha256 : {row['restored_sha']} (byte-identical to candidate)")
        lines.append("")
    (SCRATCH / "vr10-report.txt").write_text("\n".join(lines))
    survivors = [row["name"] for row in out if row["verdict"] != "KILLED"]
    print(f"\nMUTANTS={len(out)} KILLED={len(out) - len(survivors)} SURVIVORS={len(survivors)}")
    for name in survivors:
        print(f"SURVIVOR: {name}")
    return 0


sys.exit(main())
